<script setup>
import {ref,onMounted} from 'vue'
import {api} from '../boot/axios'
const rows=ref([]),total=ref(0),page=ref(1),stage=ref('all'),loading=ref(false),error=ref('')
const labels={expired:'Expirada','1h':'Até 1 hora','24h':'Até 24 horas','3d':'Até 3 dias','7d':'Até 7 dias'}
async function load(){loading.value=true;error.value='';try{const value=(await api.get('/admin/desktop-expirations',{headers:{Authorization:'Bearer '+localStorage.getItem('aito_admin_token')},params:{page:page.value,limit:30,stage:stage.value}})).data.data;rows.value=value.items;total.value=value.total}catch(e){error.value=e.response?.data?.message||'Não foi possível consultar.'}finally{loading.value=false}}
onMounted(load)
const columns=[{name:'name',label:'Cliente',field:'name',align:'left'},{name:'email',label:'E-mail',field:'email',align:'left'},{name:'expiry',label:'Expira em',field:'expiresAt',align:'left'},{name:'stage',label:'Situação',field:'stage',align:'left'},{name:'actions',label:'Ações',field:'id'}]
</script>
<template><section><h2>Desktop · vencimentos e renovações</h2><p>Clientes com licença expirada ou com vencimento nos próximos sete dias.</p><div class="row q-gutter-md q-mb-lg"><q-select dark outlined v-model="stage" emit-value map-options :options="[{label:'Todos',value:'all'},...Object.entries(labels).map(([value,label])=>({value,label}))]" label="Faixa de vencimento" style="min-width:240px" @update:model-value="page=1;load()"/><q-btn outline label="Atualizar" icon="refresh" :loading="loading" @click="load"/></div><p v-if="error" role="alert">{{error}}</p><q-table dark flat bordered :rows="rows" :columns="columns" row-key="id" :loading="loading" :pagination="{rowsPerPage:0}" hide-pagination no-data-label="Nenhum cliente nesta faixa"><template #body-cell-expiry="props"><q-td :props="props">{{new Date(props.row.expiresAt).toLocaleString('pt-BR')}}</q-td></template><template #body-cell-stage="props"><q-td :props="props"><q-badge :color="props.row.stage==='expired'?'negative':'orange-9'">{{labels[props.row.stage]}}</q-badge></q-td></template><template #body-cell-actions="props"><q-td :props="props"><q-btn flat round icon="more_horiz" disable aria-label="Ações disponíveis em breve"/><small>Em breve</small></q-td></template></q-table><q-pagination v-model="page" :max="Math.max(1,Math.ceil(total/30))" class="q-mt-md" @update:model-value="load"/></section></template>
